{
  "command": "node_modules/.bin/taproot help agents",
  "description": "Show Taproot CLI guidance for agents"
}

{
  "command": "node_modules/.bin/taproot batch --command \"search slider\" --command \"get slider --impl web\"",
  "description": "Search for slider and fetch its web implementation"
}

{
  "command": "node_modules/.bin/taproot get component.slider; echo \"-----REACT-----\"; node_modules/.bin/taproot get component.slider --impl react; echo \"-----HELP-----\"; node_modules/.bin/taproot help",
  "description": "Fetch slider record, React implementation, and CLI help"
}

{
  "command": "ls node_modules/@taproot* 2>/dev/null; grep -rIl -i \"slider\" node_modules/@taproot* --include=*.json --include=*.d.ts --include=*.md 2>/dev/null | head -20",
  "description": "Look for slider references in installed Taproot packages"
}

{
  "command": "P=node_modules/@taproot-ds/web-components; [ -d \"$P\" ] || P=node_modules/@taproot/web-components; echo \"pkg: $P\"; ls -la node_modules/ | grep -i taproot; grep -m1 '\"version\"' \"$P/package.json\"; ls \"$P\" \"$P/dist\" 2>/dev/null | head -60; echo \"--- slider refs ---\"; grep -rIli \"slider\" \"$P\" 2>/dev/null | head -20; echo \"--- impl list ---\"; node_modules/.bin/taproot list --impl web",
  "description": "Inspect web-components package for slider and list web components"
}

{
  "command": "node_modules/.bin/taproot list --impl web",
  "description": "List components with a web implementation"
}
